files.relay.ark:
pragma arkade ^0.1.0;

import "struct_vault.ark";
import "single_sig.ark";

// Moves a coin into a vault under the same policy, with a fee to a fixed key.
contract Relay(Policy policy) {
  @allow(unsigned-spend-path, "the outputs pay the vault and the fee key")
  function relay() {
    require(tx.outputs[0].script == new StructVault(policy));
    require(tx.outputs[1].script == new SingleSig(0x79be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798));
  }

  function unilateral(signature sig) tapscript {
    require(older(policy.exitDelay));
    require(checkSig(sig, policy.primary.key));
  }
}

files.single_sig.ark:
pragma arkade ^0.1.0;

contract SingleSig(
  pubkey user
) {
  // Single signature spend path
  function spend(signature userSig) {
    require(checkSig(userSig, user));
  }

  // Unilateral exit (CSV).
  function unilateral(signature userSig) tapscript {
    require(older(operatorExitDelay));
    require(checkSig(userSig, user));
  }
}

files.struct_vault.ark:
pragma arkade ^0.1.0;

struct Signer {
  pubkey key;
  int weight;
}

struct Policy {
  Signer primary;
  int[2] limits;
  int exitDelay;
}

contract StructVault(Policy policy) {
  function update(Policy next, signature sig) {
    require(checkSig(sig, policy.primary.key));

    int total = 0;
    for (i, limit) in next.limits {
      total = total + limit;
    }
    require(total >= policy.primary.weight);

    Policy local = {
      primary: {
        key: next.primary.key,
        weight: total
      },
      limits: [next.limits[0], next.limits[1]],
      exitDelay: policy.exitDelay
    };
    require(local.primary.weight == total);
  }

  function unilateral(signature sig) tapscript {
    require(older(policy.exitDelay));
    require(checkSig(sig, policy.primary.key));
  }
}
